class Solution:
    def gcd(self, a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(self, a, b):
        if a == 0 or b == 0:
            return 0
        return abs(a * b) // self.gcd(a, b)

    def get_gcd_of_list(self, arr):
        if not arr:
            return 0
        result = arr[0]
        for i in range(1, len(arr)):
            result = self.gcd(result, arr[i])
        return result

    def get_lcm_of_list(self, arr):
        if not arr:
            return 0
        result = arr[0]
        for i in range(1, len(arr)):
            result = self.lcm(result, arr[i])
        return result

    def maxScore(self, nums: List[int]) -> int:
        max_score = 0
        n = len(nums)

        # Case 1: No element removed
        current_gcd = self.get_gcd_of_list(nums)
        current_lcm = self.get_lcm_of_list(nums)
        max_score = max(max_score, current_gcd * current_lcm)

        # Case 2: One element removed
        for i in range(n):
            # Create the list after removing nums[i]
            temp_nums = nums[:i] + nums[i+1:]

            if not temp_nums:
                # Factor score of an empty array is 0
                continue

            temp_gcd = self.get_gcd_of_list(temp_nums)
            temp_lcm = self.get_lcm_of_list(temp_nums)

            max_score = max(max_score, temp_gcd * temp_lcm)

        return max_score

